<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Certificaciones de arqueos</title><style>body{font-family:system-ui,sans-serif;background:#f4f7fb;color:#183453;margin:0;padding:28px}.wrap{max-width:1150px;margin:auto;background:white;border-radius:14px;padding:26px;box-shadow:0 4px 20px #15335312}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #e3eaf3}a{color:#165ba5}h1{margin-top:0}.notice{padding:12px;background:#eaf2ff;border-radius:8px}</style></head><body><main class="wrap"><p><a href="{{ route($rutaBase.'.dashboard') }}">← Volver al panel</a></p><h1>Certificación de arqueos ordinarios</h1><p>Arqueos de las agencias a su cargo.</p>@if($arqueos->isEmpty())<p class="notice">No hay arqueos disponibles.</p>@else<div style="overflow-x:auto"><table><thead><tr><th>Número</th><th>Fecha</th><th>Agencia</th><th>Receptor</th><th>Arqueado</th><th>Diferencia</th><th>Estado</th><th>Acción</th></tr></thead><tbody>@foreach($arqueos as $arqueo)<tr><td>{{ $arqueo->numero_arqueo }}</td><td>{{ $arqueo->fecha_operativa?->format('d/m/Y') }}</td><td>{{ $arqueo->agencia_nombre_historico }}</td><td>{{ $arqueo->receptor_nombre_historico }}</td><td>Q {{ number_format((float)$arqueo->total_arqueado,2) }}</td><td>Q {{ number_format((float)$arqueo->diferencia,2) }}</td><td>{{ $arqueo->estado }}</td><td><a href="{{ route($rutaBase.'.certificaciones.show',$arqueo->id) }}">Revisar</a></td></tr>@endforeach</tbody></table></div>{{ $arqueos->links() }}@endif</main></body></html>